-- Personal layout belongs to the person, never to a project.
CREATE TABLE peg_personal_settings (operator_id TEXT PRIMARY KEY, timezone TEXT NOT NULL DEFAULT 'America/New_York', sort TEXT NOT NULL DEFAULT 'default' CHECK(sort IN ('default','manual')));
CREATE TABLE peg_personal_sections (id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, name TEXT NOT NULL, position REAL NOT NULL);
CREATE TABLE peg_personal_layout (operator_id TEXT NOT NULL, task_id TEXT NOT NULL, section_id TEXT, position REAL NOT NULL DEFAULT 0, today INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(operator_id,task_id));
CREATE TABLE peg_personal_rules (id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, group_name TEXT NOT NULL CHECK(group_name IN ('Overdue','Today','Upcoming','Later')), section_id TEXT NOT NULL);
CREATE TABLE peg_personal_moves (id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, task_id TEXT NOT NULL, rule_id TEXT NOT NULL, local_day TEXT NOT NULL, before_section TEXT, after_section TEXT NOT NULL, before_position REAL NOT NULL, undone INTEGER NOT NULL DEFAULT 0, UNIQUE(operator_id,task_id,rule_id,local_day));
CREATE TABLE peg_personal_revision (id INTEGER PRIMARY KEY CHECK(id=1), value INTEGER NOT NULL);
INSERT INTO peg_personal_revision VALUES(1,1);
CREATE TABLE peg_personal_guards (id TEXT PRIMARY KEY, revision INTEGER NOT NULL);
CREATE TRIGGER peg_personal_guard BEFORE INSERT ON peg_personal_guards BEGIN
 SELECT CASE WHEN NEW.revision<>(SELECT value FROM peg_personal_revision WHERE id=1) THEN RAISE(ABORT,'stale_personal_preview') END;
END;
CREATE TRIGGER peg_personal_rev_peg_tasks_insert AFTER INSERT ON peg_tasks BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_personal_rev_peg_tasks_update AFTER UPDATE ON peg_tasks BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_personal_rev_peg_tasks_delete AFTER DELETE ON peg_tasks BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
